oad.join(\\"usr/bin/droidloom-update\\"))\\n            .arg(\\"apply\\")\\n            .arg(&payload)\\n            .arg(\\"--uid\\")\\n            .arg(uid.to_string()))?;\\n    }\\n    Ok(())\\n}\\nfn main() {\\n    if let Err(error) = execute(Args::parse()) {\\n        eprintln!(\\"Droidloom update failed: {error}\\");\\n        std::process::exit(1);\\n    }\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    #[test]\\n    fn native_generation_pair_cli_requires_one_explicit_product() {\\n        assert!(Args::try_parse_from([\\"droidloom-update\\", \\"native-generation-pair\\"]).is_err());\\n        assert!(Args::try_parse_from([\\"droidloom-update\\", \\"native-generation-pair\\",\\n            \\"--product\\", \\"/not-executed\\", \\"libart\\"]).is_err());\\n        let args = Args::try_parse_from([\\"droidloom-update\\", \\"native-generation-pair\\",\\n            \\"--product\\", \\"/not-executed\\"]).unwrap();\\n        assert!(matches!(args.command, Some(Action::NativeGenerationPair { product })\\n            if product == PathBuf::from(\\"/not-executed\\")));\\n    }\\n\\n    #[test]\\n    fn native_engine_cli_requires_prepared_workspace_and_has_no_arbitrary_targets() {\\n        assert!(Args::try_parse_from([\\"droidloom-update\\", \\"native-engine-build\\"]).is_err());\\n        assert!(Args::try_parse_from([\\"droidloom-update\\", \\"native-engine-build\\",\\n            \\"--work\\", \\"/not-executed\\", \\"services\\"]).is_err());\\n        let args = Args::try_parse_from([\\"droidloom-update\\", \\"-j\\", \\"2\\", \\"native-engine-build\\",\\n            \\"--work\\", \\"/not-executed\\", \\"--tests\\"]).unwrap();\\n        assert!(matches!(args.command, Some(Action::NativeEngineBuild { tests: true, .. })));\\n    }\\n\\n    #[test]\\n    fn native_engine_output_selector_keeps_default_or_exact_explicit_directory() {\\n        let work = std::path::Path::new(\\"/prepared\\");\\n        let parse = |extra: &[&str]| {\\n            let mut argv = vec![\\"droidloom-update\\", \\"native-engine-build\\", \\"--work\\", \\"/prepared\\", \\"--tests\\"];\\n            argv.extend_from_slice(extra);\\n            Args::try_parse_from(argv).unwrap()\\n        };\\n        let args = parse(&[]);\\n        assert_eq!(selected_build_out(args.command.as_ref(), work).unwrap(),\\n            work.join(\\"android-native-engine-out\\"));\\n        let args = parse(&[\\"--out\\", \\"/prepared/android-native-engine-out-r9\\"]);\\n        assert_eq!(selected_build_out(args.command.as_ref(), work).unwrap(),\\n            PathBuf::from(\\"/prepared/android-native-engine-out-r9\\"));\\n        for path in [\\"relative-out\\", \\"/prepared\\", \\"/prepared/aosp-source\\", \\"/prepared/aosp-source/out\\", \\"/prepared/new/../old\\"] {\\n            let args = parse(&[\\"--out\\", path]);\\n            assert!(selected_build_out(args.command.as_ref(), work).is_err(), \\"{path}\\");\\n        }\\n        let temp = tempfile::tempdir().unwrap();\\n        let alias = temp.path().join(\\"alias\\");\\n        std::os::unix::fs::symlink(temp.path(), &alias).unwrap();\\n        let args = parse(&[\\"--out\\", alias.join(\\"new-out\\").to_str().unwrap()]);\\n        assert!(selected_build_out(args.command.as_ref(), work).is_err());\\n    }\\n}\\n", "delta/tools/droidloom-update/src/native_bridge.rs": "//! Source-built ARM64 NativeBridge support for the x86_64 Android cell.\\nuse crate::util::*;\\nuse serde::Deserialize;\\nuse std::{\\n    collections::{BTreeMap, BTreeSet},\\n    fs,\\n    path::{Path, PathBuf},\\n    process::Command,\\n};\\n\\n#[derive(Deserialize)]\\n#[serde(deny_unknown_fields)]\\nstruct SourceLock {\\n    schema_version: u32,\\n    name: String,\\n    url: String,\\n    commit: String,\\n    license: String,\\n    path: String,\\n}\\n\\n// These are already supplied by the checksum-pinned system image. Link only\\n// the translator\'s proxies against them; do not replace source-built platform\\n// modules or install these build references as a second runtime provider.\\nconst HOST_API_LIBRARIES: &[&str] = &[\\n    \\"libandroid\\",\\n    \\"libandroid_runtime\\",\\n    \\"libaaudio\\",\\n    \\"libamidi\\",\\n    \\"libbinder_ndk\\",\\n    \\"libcamera2ndk\\",\\n    \\"libEGL\\",\\n    \\"libGLESv1_CM\\",\\n    \\"libGLESv2\\",\\n    \\"libGLESv3\\",\\n    \\"libjnigraphics\\",\\n    \\"libmediandk\\",\\n    \\"libnativewindow\\",\\n    \\"libnativehelper\\",\\n    \\"libneuralnetworks\\",\\n    \\"libOpenMAXAL\\",\\n    \\"libOpenSLES\\",\\n    \\"libwebviewchromium_plat_support\\",\\n    \\"libvulkan\\",\\n];\\n\\npub fn prepare_build(\\n    source: &Path,\\n    vendor: &Path,\\n    work: &Path,\\n    projection: &mut crate::android::Projection,\\n) -> Result<()> {\\n    let bridge = source.join(\\"frameworks/libs/binary_translation\\");\\n    // Android 17 forbids global libnativehelper include paths. Export its\\n    // platform API declarations through a local header-only module instead.\\n    let nativehelper = source.join(\\"libnativehelper/Android.bp\\");\\n    projection.put(\\n        &nativehelper,\\n        fs::read_to_string(&nativehelper)?\\n            + r#\\"\\ncc_library_headers {\\n    name: \\"droidloom_native_bridge_nativehelper_headers\\",\\n    export_include_dirs: [\\"include\\"],\\n    header_libs: [\\"jni_headers\\"],\\n    export_header_lib_headers: [\\"jni_headers\\"],\\n}\\n\\"#,\\n    )?;\\n    let link = vendor.join(\\"android/native-bridge/link\\");\\n    fs::create_dir_all(&link)?;\\n    let mut blueprint =\\n        String::from(\\"package { default_applicable_licenses: [\\\\\\"Android-Apache-2.0\\\\\\"], }\\\\n\\");\\n    for name in HOST_API_LIBRARIES {\\n        let library = work.join(format!(\\"base-system/system/lib64/{name}.so\\"));\\n        let apex_name = match *name {\\n            \\"libneuralnetworks\\" => Some(\\"com.android.neuralnetworks\\"),\\n            \\"libnativehelper\\" => Some(\\"com.android.art\\"),\\n            _ => None,\\n        };\\n        if let Some(apex_name) = apex_name {\\n            let apex = work.join(format!(\\"base-system/system/apex/{apex_name}.apex\\"));\\n            let scratch = tempfile::Builder::new()\\n                .prefix(\\"native-bridge-apex-\\")\\n                .tempdir_in(work)?;\\n            let payload = scratch.path().join(\\"payload.img\\");\\n            run(Command::new(\\"unzip\\")\\n                .args([\\"-p\\"])\\n                .arg(&apex)\\n                .arg(\\"apex_payload.img\\")\\n                .stdout(std::process::Stdio::from(fs::File::create(&payload)?)))?;\\n            // This pinned Mainline APEX uses ext4, unlike the system EROFS.\\n            // debugfs opens it read-only and streams exactly the requested ELF.\\n            run(Command::new(\\"debugfs\\")\\n                .arg(\\"-R\\")\\n                .arg(format!(\\"cat /lib64/{name}.so\\"))\\n                .arg(&payload)\\n                .stdout(std::process::Stdio::from(fs::File::create(\\n                    link.join(format!(\\"{name}.so\\")),\\n                )?)))?;\\n        } else {\\n            copy(&library, &link.join(format!(\\"{name}.so\\")))?;\\n        }\\n        let bytes = fs::read(link.join(format!(\\"{name}.so\\")))?;\\n        if bytes.len() < 20\\n            || &bytes[..6] != b\\"\\\\x7fELF\\\\x02\\\\x01\\"\\n            || u16::from_le_bytes([bytes[18], bytes[19]]) != 62\\n        {\\n            return fail(format!(\\"invalid pinned x86_64 API library: {name}\\"));\\n        }\\n        blueprint.push_str(&format!(\\n            r#\\"\\ncc_prebuilt_library_shared {{\\n    name: \\"droidloom_native_bridge_host_{name}\\",\\n    stem: \\"{name}\\", srcs: [\\"{name}.so\\"],\\n    compile_multilib: \\"64\\", installable: false,\\n    system_shared_libs: [], shared_libs: [],\\n    header_libs: [\\"libnativewindow_headers\\", \\"libarect_headers\\", \\"libutils_headers\\", \\"droidloom_native_bridge_nativehelper_headers\\"],\\n    export_header_lib_headers: [\\"libnativewindow_headers\\", \\"libarect_headers\\", \\"libutils_headers\\", \\"droidloom_native_bridge_nativehelper_headers\\"],\\n    // Dependencies are provided by the pinned runtime, outside this build graph.\\n    check_elf_files: false, strip: {{ none: true }},\\n}}\\n\\"#\\n        ));\\n    }\\n    write(&link.join(\\"Android.bp\\"), blueprint)?;\\n    // The engine itself uses libandroid for native activity integration.\\n    for relative in [\\"Android.bp\\", \\"native_activity/Android.bp\\"] {\\n        let root = bridge.join(relative);\\n        projection.put(\\n            &root,\\n            fs::read_to_string(&root)?.replace(\\n                \\"\\\\\\"libandroid\\\\\\"\\",\\n                \\"\\\\\\"droidloom_native_bridge_host_libandroid\\\\\\"\\",\\n            ),\\n        )?;\\n    }\\n    for entry in fs::read_dir(bridge.join(\\"android_api\\"))? {\\n        let path = entry?.path().join(\\"Android.bp\\");\\n        if !path.is_file() {\\n            continue;\\n        }\\n        let mut text = fs::read_to_string(&path)?;\\n        for name in HOST_API_LIBRARIES {\\n            text = text.replace(\\n                &format!(\\"\\\\\\"{name}\\\\\\"\\"),\\n                &format!(\\"\\\\\\"droidloom_native_bridge_host_{name}\\\\\\"\\"),\\n            );\\n        }\\n        projection.put(&path, text)?;\\n    }\\n    let defaults = bridge.join(\\"android_api/Android.bp\\");\\n    let text = fs::read_to_string(&defaults)?.replace(\\n        \\"host_supported: false,\\",\\n        r#\\"host_supported: false,\\n    include_dirs: [\\n        \\"external/vulkan-headers/include\\",\\n        \\"frameworks/base/core/jni/include\\",\\n        \\"frameworks/wilhelm/include\\",\\n        \\"frameworks/av/media/ndk/include\\",\\n        \\"frameworks/av/media/libaaudio/include\\",\\n        \\"frameworks/base/media/native/midi/include\\",\\n        \\"frameworks/av/camera/ndk/include\\",\\n        \\"frameworks/native/libs/nativewindow/include\\",\\n        \\"frameworks/native/libs/binder/ndk/include_ndk\\",\\n    ],\\"#,\\n    );\\n    projection.put(&defaults, text)?;\\n    // This pinned Digitalis revision leaves the old atomic fault-check flag\\n    // unused after switching to fault-recoverable atomic builtins.\\n    let interpreter = bridge.join(\\"interpreter/arm64/interpreter.h\\");\\n    projection.put(\\n        &interpreter,\\n        fs::read_to_string(&interpreter)?.replace(\\n            \\"    bool need_write = (args.op != Decoder::AtomicOp::kLdxr &&\\\\n                       args.op != Decoder::AtomicOp::kLdar);\\\\n\\",\\n            \\"\\",\\n        ),\\n    )?;\\n    // Android 17 moved these declarations; Digitalis still keeps them in\\n    // runtime_primitives. Adapt the header dependency and the three include paths.\\n    let support = source.join(\\"frameworks/libs/native_bridge_support\\");\\n    let libc = support.join(\\"android_api/libc/Android.bp\\");\\n    projection.put(\\n        &libc,\\n        fs::read_to_string(&libc)?\\n            .replace(\\"        \\\\\\"libberberis_runtime_library_headers\\\\\\",\\\\n\\", \\"\\"),\\n    )?;\\n    for relative in [\\n        \\"android_api/libEGL/proxy/egl_trampolines.cc\\",\\n        \\"android_api/libvulkan/proxy/vulkan_trampolines.cc\\",\\n        \\"android_api/libvulkan/proxy/vulkan_xml.h\\",\\n    ] {\\n        let path = support.join(relative);\\n        projection.put(\\n            &path,\\n            fs::read_to_string(&path)?.replace(\\n                \\"berberis/runtime_library/runtime_library.h\\",\\n                \\"berberis/runtime_primitives/runtime_library.h\\",\\n            ),\\n        )?;\\n    }\\n    Ok(())\\n}\\n\\nconst PROPERTIES: &[(&str, &str)] = &[\\n    (\\"ro.dalvik.vm.native.bridge\\", \\"libberberis_arm64.so\\"),\\n    (\\"ro.dalvik.vm.isa.arm64\\", \\"x86_64\\"),\\n    (\\"ro.enable.native.bridge.exec\\", \\"0\\"),\\n    (\\"ro.berberis.flags\\", \\"android-mmap-noreserve\\"),\\n    (\\"ro.product.cpu.abilist\\", \\"x86_64,arm64-v8a\\"),\\n    (\\"ro.product.cpu.abilist64\\", \\"x86_64,arm64-v8a\\"),\\n    (\\"ro.product.cpu.abilist32\\", \\"\\"),\\n    (\\"ro.system.product.cpu.abilist\\", \\"x86_64,arm64-v8a\\"),\\n    (\\"ro.system.product.cpu.abilist64\\", \\"x86_64,arm64-v8a\\"),\\n    (\\"ro.system.product.cpu.abilist32\\", \\"\\"),\\n];\\n\\nfn bridge_properties(original: &str) -> Result<String> {\\n    if !original\\n        .lines()\\n        .any(|line| line == \\"ro.build.version.sdk=37\\")\\n    {\\n        return fail(\\"ARM64 translation requires the pinned Android 17 system image\\");\\n    }\\n    let mut result = String::new();\\n    for line in original.lines() {\\n        if !PROPERTIES.iter().any(|(key, _)| {\\n            line.split_once(\'=\')\\n                .is_some_and(|(existing, _)| existing.trim() == *key)\\n        }) {\\n            result.push_str(line);\\n            result.push(\'\\\\n\');\\n        }\\n    }\\n    result.push_str(\\"\\\\n# Droidloom source-built ARM64 NativeBridge\\\\n\\");\\n    for (key, value) in PROPERTIES {\\n        result.push_str(&format!(\\"{key}={value}\\\\n\\"));\\n    }\\n    Ok(result)\\n}\\n\\npub fn stage_image(repo: &Path, image: &Path, destination: &Path, product: &Path) -> Result<()> {\\n    fs::create_dir_all(destination.parent().ok_or(\\"image has no parent\\")?)?;\\n    let worker = tempfile::Builder::new()\\n        .prefix(\\"native-bridge-worker-\\")\\n        .tempdir_in(destination.parent().unwrap())?;\\n    let executable = worker.path().join(\\"droidloom-update\\");\\n    fs::copy(\\"/proc/self/exe\\", &executable)?;\\n    mode(&executable, 0o755)?;\\n    run(Command::new(\\"fakeroot\\")\\n        .arg(\\"--\\")\\n        .arg(executable)\\n        .arg(\\"native-bridge-image\\")\\n        .arg(\\"--image\\")\\n        .arg(image)\\n        .arg(\\"--destination\\")\\n        .arg(destination)\\n        .arg(\\"--product\\")\\n        .arg(product)\\n        .arg(\\"--source-lock\\")\\n        .arg(repo.join(\\"android/manifest/native-bridge-lock.json\\")))\\n}\\n\\nfn guest_files(root: &Path, paths: &mut Vec<PathBuf>) -> Result<()> {\\n    for entry in fs::read_dir(root)? {\\n        let entry = entry?;\\n        if entry.file_type()?.is_dir() {\\n            guest_files(&entry.path(), paths)?;\\n        } else {\\n            paths.push(entry.path());\\n        }\\n    }\\n    Ok(())\\n}\\n\\n/// Rebuild the system EROFS in one fakeroot session, retaining its metadata.\\npub fn derive_image(\\n    image: &Path,\\n    destination: &Path,\\n    product: &Path,\\n    source_lock: &Path,\\n) -> Result<()> {\\n    if std::env::var_os(\\"FAKEROOTKEY\\").is_none() {\\n        return fail(\\"NativeBridge image assembly requires fakeroot metadata preservation\\");\\n    }\\n    if destination.exists() {\\n        return fail(\\"NativeBridge image destination already exists\\");\\n    }\\n    let work = tempfile::Builder::new()\\n        .prefix(\\"native-bridge-image-\\")\\n        .tempdir_in(destination.parent().ok_or(\\"image has no parent\\")?)?;\\n    let tree = work.path().join(\\"tree\\");\\n    crate::image_policy::extract(image, &tree)?;\\n    let properties = tree.join(\\"system/build.prop\\");\\n    let updated = bridge_properties(&fs::read_to_string(&properties)?)?;\\n    fs::write(&properties, updated)?;\\n\\n    let mut paths = Vec::new();\\n    for entry in fs::read_dir(product.join(\\"system/lib64\\"))? {\\n        let entry = entry?;\\n        if entry\\n            .file_name()\\n            .to_string_lossy()\\n            .starts_with(\\"libberberis_\\")\\n            && entry.file_name().to_string_lossy().ends_with(\\".so\\")\\n        {\\n            paths.push(entry.path());\\n        }\\n    }\\n    guest_files(&product.join(\\"system/lib64/arm64\\"), &mut paths)?;\\n    guest_files(&product.join(\\"system/bin/arm64\\"), &mut paths)?;\\n    paths.push(product.join(\\"system/etc/ld.config.arm64.txt\\"));\\n    paths.sort();\\n    for required in [\\n        \\"system/lib64/libberberis_arm64.so\\",\\n        \\"system/lib64/libberberis_exec_region.so\\",\\n        \\"system/lib64/libberberis_proxy_libc.so\\",\\n        \\"system/lib64/libberberis_proxy_libEGL.so\\",\\n        \\"system/lib64/libberberis_proxy_libGLESv2.so\\",\\n        \\"system/lib64/libberberis_proxy_libvulkan.so\\",\\n        \\"system/lib64/arm64/libc.so\\",\\n        \\"system/lib64/arm64/libnative_bridge_vdso.so\\",\\n        \\"system/bin/arm64/linker64\\",\\n    ] {\\n        if !paths.contains(&product.join(required)) {\\n            return fail(format!(\\"missing required NativeBridge output: {required}\\"));\\n        }\\n    }\\n    let mut inventory = BTreeMap::new();\\n    let mut directories = BTreeSet::new();\\n    for path in paths {\\n        let relative = path.strip_prefix(product)?;\\n        let destination = tree.join(relative);\\n        let metadata = fs::symlink_metadata(&path)?;\\n        fs::create_dir_all(destination.parent().unwrap())?;\\n        for parent in relative.ancestors().skip(1) {\\n            if parent.starts_with(\\"system/lib64/arm64\\") || parent.starts_with(\\"system/bin/arm64\\") {\\n                directories.insert(tree.join(parent));\\n            }\\n        }\\n        if metadata.file_type().is_symlink() {\\n            let target = fs::read_link(&path)?;\\n            // Preserve relative links only when their target stays in the product.\\n            if target.is_absolute() || !path.canonicalize()?.starts_with(product.canonicalize()?) {\\n                return fail(format!(\\n                    \\"unsupported guest runtime symlink: {}\\",\\n                    path.display()\\n                ));\\n            }\\n            inventory.insert(\\n                relative.to_string_lossy().into_owned(),\\n                format!(\\"link:{}\\", target.display()),\\n            );\\n        } else if metadata.is_file() {\\n            let bytes = fs::read(&path)?;\\n            if bytes.starts_with(b\\"\\\\x7fELF\\") {\\n                let guest = relative.starts_with(\\"system/lib64/arm64\\")\\n                    || relative.starts_with(\\"system/bin/arm64\\");\\n                let machine = if guest { 183u16 } else { 62u16 };\\n                if bytes.len() < 20\\n                    || bytes[4] != 2\\n                    || bytes[5] != 1\\n                    || u16::from_le_bytes([bytes[18], bytes[19]]) != machine\\n                {\\n                    return fail(format!(\\n                        \\"wrong NativeBridge ELF architecture: {}\\",\\n                        path.display()\\n                    ));\\n                }\\n            } else if relative != Path::new(\\"system/etc/ld.config.arm64.txt\\") {\\n                return fail(format!(\\n                    \\"non-ELF NativeBridge runtime output: {}\\",\\n                    path.display()\\n                ));\\n            }\\n            inventory.insert(relative.to_string_lossy().into_owned(), hash(&path)?);\\n        } else {\\n            return fail(\\"unsupported NativeBridge runtime object\\");\\n        }\\n        run(Command::new(\\"cp\\")\\n            .args([\\"-a\\", \\"--remove-destination\\", \\"--\\"])\\n            .arg(&path)\\n            .arg(&destination))?;\\n        run(Command::new(\\"chown\\").args([\\"-h\\", \\"0:0\\"]).arg(&destination))?;\\n        let label = if relative.starts_with(\\"system/lib64\\") {\\n            \\"u:object_r:system_lib_file:s0\\"\\n        } else {\\n            \\"u:object_r:system_file:s0\\"\\n        };\\n        run(Command::new(\\"setfattr\\")\\n            .args([\\"-h\\", \\"-n\\", \\"security.selinux\\", \\"-v\\", label])\\n            .arg(&destination))?;\\n    }\\n    for directory in directories {\\n        run(Command::new(\\"chown\\").arg(\\"0:0\\").arg(&directory))?;\\n        mode(&directory, 0o755)?;\\n        run(Command::new(\\"setfattr\\")\\n            .args([\\n                \\"-n\\",\\n                \\"security.selinux\\",\\n                \\"-v\\",\\n                if directory.starts_with(tree.join(\\"system/lib64\\")) {\\n                    \\"u:object_r:system_lib_file:s0\\"\\n                } else {\\n                    \\"u:object_r:system_file:s0\\"\\n                },\\n            ])\\n            .arg(&directory))?;\\n    }\\n    let native_generation = crate::native_generation::stage_product(product, &tree)?;\\n    if native_generation.is_some() {\\n        for relative in [\\n            \\"system/apex/com.android.art.apex\\",\\n            crate::native_generation::TREE_RECORD,\\n        ] {\\n            inventory.insert(relative.to_string(), hash(&tree.join(relative))?);\\n        }\\n    }\\n    let manifest = serde_json::json!({\\n        \\"native_generation\\": native_generation,\\n        \\"schema_version\\": 1,\\n        \\"source\\": serde_json::from_slice::<serde_json::Value>(&fs::read(source_lock)?)?,\\n        \\"build_source\\": serde_json::from_slice::<serde_json::Value>(&fs::read(\\n            product.join(\\"droidloom-native-bridge-source.json\\"))?)?,\\n        \\"guest_abi\\": \\"arm64-v8a\\", \\"host_abi\\": \\"x86_64\\",\\n        \\"native_executables\\": false, \\"files\\": inventory,\\n    });\\n    let manifest_path = tree.join(\\"system/etc/droidloom-native-bridge.json\\");\\n    fs::write(&manifest_path, serde_json::to_vec_pretty(&manifest)?)?;\\n    run(Command::new(\\"chown\\").arg(\\"0:0\\").arg(&manifest_path))?;\\n    run(Command::new(\\"setfattr\\")\\n        .args([\\"-n\\", \\"security.selinux\\", \\"-v\\", \\"u:object_r:system_file:s0\\"])\\n        .arg(&manifest_path))?;\\n    let expected = crate::image_policy::inventory(&tree)?;\\n    let rebuilt = work.path().join(\\"system.img\\");\\n    run(Command::new(\\"mkfs.erofs\\")\\n        // makepkg exports SOURCE_DATE_EPOCH, which otherwise silently clamps\\n        // newer mtimes despite --preserve-mtime. Preserve the staged metadata\\n        // exactly; the filesystem creation timestamp is explicitly pinned below.\\n        .env_remove(\\"SOURCE_DATE_EPOCH\\")\\n        .args([\\n            \\"-zlz4hc,level=9\\",\\n            \\"--workers=2\\",\\n            \\"-T1230768000\\",\\n            \\"--mkfs-time\\",\\n            \\"--preserve-mtime\\",\\n            \\"-U166f4792-a27c-43a9-a1b7-e5d5c6e8ac5b\\",\\n        ])\\n        .arg(&rebuilt)\\n        .arg(&tree))?;\\n    let checked = work.path().join(\\"checked\\");\\n    crate::image_policy::extract(&rebuilt, &checked)?;\\n    let actual = crate::image_policy::inventory(&checked)?;\\n    if actual != expected {\\n        for path in expected\\n            .keys()\\n            .chain(actual.keys())\\n            .collect::<BTreeSet<_>>()\\n        {\\n            if expected.get(path) != actual.get(path) {\\n                eprintln!(\\n                    \\"NativeBridge image mismatch at {}: expected {:?}, got {:?}\\",\\n                    path.display(),\\n                    expected.get(path),\\n                    actual.get(path)\\n                );\\n            }\\n        }\\n        return fail(\\"NativeBridge image verification found changed contents or metadata\\");\\n    }\\n    fs::rename(&rebuilt, destination)?;\\n    eprintln!(\\n        \\"Verified ARM64 NativeBridge system image: {}\\",\\n        destination.display()\\n    );\\n    Ok(())\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    const LOCK: &str = include_str!(\\"../../../android/manifest/native-bridge-lock.json\\");\\n\\n    fn git(dir: &Path, args: &[&str]) -> String {\\n        output(\\n            Command::new(\\"git\\")\\n                .arg(\\"-C\\")\\n                .arg(dir)\\n                .args([\\n                    \\"-c\\",\\n                    \\"user.name=Droidloom Test\\",\\n                    \\"-c\\",\\n                    \\"user.email=test@example.invalid\\",\\n                    \\"-c\\",\\n                    \\"commit.gpgsign=false\\",\\n                ])\\n                .args(args),\\n        )\\n        .unwrap()\\n    }\\n\\n    fn source_fixture() -> (tempfile::TempDir, PathBuf, PathBuf, PathBuf) {\\n        let root = tempfile::tempdir().unwrap();\\n        let repo = root.path().join(\\"repo\\");\\n        let source = root.path().join(\\"source\\");\\n        let checkout = source.join(\\"frameworks/libs/binary_translation\\");\\n        fs::create_dir_all(repo.join(\\"android/manifest\\")).unwrap();\\n        fs::create_dir_all(&checkout).unwrap();\\n        git(&checkout, &[\\"init\\", \\"--quiet\\"]);\\n        let mut lock: serde_json::Value = serde_json::from_str(LOCK).unwrap();\\n        git(\\n            &checkout,\\n            &[\\"remote\\", \\"add\\", \\"origin\\", lock[\\"url\\"].as_str().unwrap()],\\n        );\\n        fs::write(checkout.join(\\"README.md\\"), \\"fixture\\\\n\\").unwrap();\\n        git(&checkout, &[\\"add\\", \\"README.md\\"]);\\n        git(&checkout, &[\\"commit\\", \\"--quiet\\", \\"-m\\", \\"fixture\\"]);\\n        lock[\\"commit\\"] = git(&checkout, &[\\"rev-parse\\", \\"HEAD\\"]).into();\\n        fs::write(\\n            repo.join(\\"android/manifest/native-bridge-lock.json\\"),\\n            serde_json::to_vec(&lock).unwrap(),\\n        )\\n        .unwrap();\\n        (root, repo, source, checkout)\\n    }\\n\\n    #[test]\\n    fn source_lock_accepts_only_teto_and_valid_contract() {\\n        let original: serde_json::Value = serde_json::from_str(LOCK).unwrap();\\n        validate_source_lock(&serde_json::from_value(original.clone()).unwrap()).unwrap();\\n        for (key, value) in [\\n            (\\n                \\"url\\",\\n                serde_json::json!(\\n                    \\"https://github.com/DigitalisX64/platform_frameworks_libs_binary_translation.git\\"\\n                ),\\n            ),\\n            (\\n                \\"url\\",\\n                serde_json::json!(\\n                    \\"https://github.com/denialwm/platform_frameworks_libs_binary_translation.git\\"\\n                ),\\n            ),\\n            (\\n                \\"url\\",\\n                serde_json::json!(\\"https://example.invalid/translator.git\\"),\\n            ),\\n            (\\"commit\\", serde_json::json!(\\"main\\")),\\n            (\\"commit\\", serde_json::json!(\\"Z\\".repeat(40))),\\n            (\\"path\\", serde_json::json!(\\"../outside\\")),\\n            (\\"license\\", serde_json::json!(\\"unknown\\")),\\n            (\\"schema_version\\", serde_json::json!(2)),\\n        ] {\\n            let mut lock = original.clone();\\n            lock[key] = value;\\n            assert!(\\n                validate_source_lock(&serde_json::from_value(lock).unwrap()).is_err(),\\n                \\"{key}\\"\\n            );\\n        }\\n    }\\n\\n    #[test]\\n    fn locked_source_rejects_dirty_wrong_origin_and_wrong_revision() {\\n        let (_root, repo, source, checkout) = source_fixture();\\n        let result = prepare_source_with_local(&repo, &source, None).unwrap();\\n        assert_eq!(result[\\"working_tree\\"], false);\\n        fs::write(checkout.join(\\"README.md\\"), \\"modified\\\\n\\").unwrap();\\n        assert!(prepare_source_with_local(&repo, &source, None).is_err());\\n        fs::write(checkout.join(\\"README.md\\"), \\"fixture\\\\n\\").unwrap();\\n        fs::write(checkout.join(\\"untracked\\"), \\"local\\\\n\\").unwrap();\\n        assert!(prepare_source_with_local(&repo, &source, None).is_err());\\n        fs::remove_file(checkout.join(\\"untracked\\")).unwrap();\\n        let origin = git(&checkout, &[\\"remote\\", \\"get-url\\", \\"origin\\"]);\\n        git(\\n            &checkout,\\n            &[\\n                \\"remote\\",\\n                \\"set-url\\",\\n                \\"origin\\",\\n                \\"https://example.invalid/other.git\\",\\n            ],\\n        );\\n        assert!(prepare_source_with_local(&repo, &source, None).is_err());\\n        git(&checkout, &[\\"remote\\", \\"set-url\\", \\"origin\\", &origin]);\\n        git(\\n            &checkout,\\n            &[\\n                \\"commit\\",\\n                \\"--allow-empty\\",\\n                \\"--quiet\\",\\n                \\"-m\\",\\n                \\"different revision\\",\\n            ],\\n        );\\n        assert!(prepare_source_with_local(&repo, &source, None).is_err());\\n    }\\n\\n    #[test]\\n    fn development_source_requires_fork_ancestry_and_records_working_files() {\\n        let (root, repo, source, checkout) = source_fixture();\\n        assert!(prepare_source_with_local(&repo, &source, Some(checkout.clone())).is_err());\\n        let local = root.path().join(\\"development\\");\\n        fs::rename(checkout, &local).unwrap();\\n        git(\\n            &local,\\n            &[\\"commit\\", \\"--allow-empty\\", \\"--quiet\\", \\"-m\\", \\"development\\"],\\n        );\\n        fs::write(local.join(\\"README.md\\"), \\"uncommitted development\\\\n\\").unwrap();\\n        let result = prepare_source_with_local(&repo, &source, Some(local.clone())).unwrap();\\n        assert_eq!(result[\\"working_tree\\"], true);\\n        assert_eq!(result[\\"commit\\"], git(&local, &[\\"rev-parse\\", \\"HEAD\\"]));\\n        assert_ne!(result[\\"commit\\"], result[\\"base_commit\\"]);\\n        assert_eq!(\\n            result[\\"files\\"][\\"README.md\\"],\\n            hash(&local.join(\\"README.md\\")).unwrap()\\n        );\\n        let lock_path = repo.join(\\"android/manifest/native-bridge-lock.json\\");\\n        let original = fs::read(&lock_path).unwrap();\\n        let mut lock: serde_json::Value = serde_json::from_slice(&original).unwrap();\\n        lock[\\"commit\\"] = \\"0\\".repeat(40).into();\\n        fs::write(&lock_path, serde_json::to_vec(&lock).unwrap()).unwrap();\\n        assert!(prepare_source_with_local(&repo, &source, Some(local.clone())).is_err());\\n        fs::write(&lock_path, original).unwrap();\\n        git(\\n            &local,\\n            &[\\n                \\"remote\\",\\n                \\"set-url\\",\\n                \\"origin\\",\\n                \\"https://example.invalid/other.git\\",\\n            ],\\n        );\\n        assert!(prepare_source_with_local(&repo, &source, Some(local)).is_err());\\n    }\\n\\n    #[test]\\n    fn native_engine_snapshot_keeps_untracked_required_source_and_propagates_deletion() {\\n        let (root, repo, source, checkout) = source_fixture();\\n        let local = root.path().join(\\"development\\");\\n        fs::rename(&checkout, &local).unwrap();\\n        let relative = \\"guest_os_primitives/guest_stack_test.cc\\";\\n        write(&local.join(relative), \\"// required untracked stack regression\\\\n\\").unwrap();\\n        assert_eq!(git(&local, &[\\"ls-files\\", relative]), \\"\\");\\n        let snapshot = prepare_source_with_local(&repo, &source, Some(local.clone())).unwrap();\\n        assert_eq!(snapshot[\\"working_tree\\"], true);\\n        assert_eq!(snapshot[\\"files\\"][relative], hash(&local.join(relative)).unwrap());\\n        assert_eq!(fs::read(checkout.join(relative)).unwrap(), fs::read(local.join(relative)).unwrap());\\n\\n        fs::remove_file(local.join(relative)).unwrap();\\n        let next = prepare_source_with_local(&repo, &source, Some(local.clone())).unwrap();\\n        assert!(next[\\"files\\"].get(relative).is_none());\\n        assert!(!checkout.join(relative).exists());\\n\\n        let outside = root.path().join(\\"outside.cc\\");\\n        write(&outside, \\"must not enter source snapshot\\\\n\\").unwrap();\\n        std::os::unix::fs::symlink(&outside, local.join(\\"escaping.cc\\")).unwrap();\\n        assert!(prepare_source_with_local(&repo, &source, Some(local)).is_err());\\n        assert!(!checkout.join(\\"escaping.cc\\").exists());\\n    }\\n\\n    #[test]\\n    fn local_snapshot_rebuilds_old_mtime_content_and_preserves_identical_import() {\\n        let (root, repo, source, checkout) = source_fixture();\\n        let local = root.path().join(\\"development\\");\\n        fs::rename(&checkout, &local).unwrap();\\n        let input = local.join(\\"README.md\\");\\n        let old_time = std::time::UNIX_EPOCH + std::time::Duration::from_secs(10_000);\\n        fs::File::open(&input).unwrap().set_modified(old_time).unwrap();\\n        prepare_source_with_local(&repo, &source, Some(local.clone())).unwrap();\\n        let imported = checkout.join(\\"README.md\\");\\n        let result = root.path().join(\\"result\\");\\n        write(&root.path().join(\\"build.ninja\\"), format!(\\n            \\"rule compile\\\\n  command = cp $in $out\\\\nbuild result: compile {}\\\\n\\",\\n            imported.display())).unwrap();\\n        let ninja = || output(Command::new(\\"ninja\\").current_dir(root.path())).unwrap();\\n        ninja();\\n        assert_eq!(fs::read(&result).unwrap(), b\\"fixture\\\\n\\");\\n        let first_output_time = fs::metadata(&result).unwrap().modified().unwrap();\\n\\n        // Same-size, same-old-mtime changes defeat rsync\'s ordinary quick\\n        // check. The real import must compare bytes and make Ninja rebuild.\\n        fs::write(&input, b\\"second!\\\\n\\").unwrap();\\n        fs::File::open(&input).unwrap().set_modified(old_time).unwrap();\\n        prepare_source_with_local(&repo, &source, Some(local.clone())).unwrap();\\n        assert_eq!(fs::read(&imported).unwrap(), b\\"second!\\\\n\\");\\n        let imported_time = fs::metadata(&imported).unwrap().modified().unwrap();\\n        assert!(imported_time > first_output_time);\\n        assert!(!ninja().contains(\\"no work to do\\"));\\n        assert_eq!(fs::read(&result).unwrap(), b\\"second!\\\\n\\");\\n        assert_eq!(fs::metadata(&input).unwrap().modified().unwrap(), old_time);\\n\\n        // An unrelated source timestamp change must not rewrite identical\\n        // destination bytes or cause unnecessary compilation.\\n        let second_output_time = fs::metadata(&result).unwrap().modified().unwrap();\\n        let different_old_time = old_time + std::time::Duration::from_secs(1);\\n        fs::File::open(&input).unwrap().set_modified(different_old_time).unwrap();\\n        prepare_source_with_local(&repo, &source, Some(local)).unwrap();\\n        assert_eq!(fs::metadata(&imported).unwrap().modified().unwrap(), imported_time);\\n        assert!(ninja().contains(\\"no work to do\\"));\\n        assert_eq!(fs::metadata(&result).unwrap().modified().unwrap(), second_output_time);\\n        assert_eq!(fs::read(&input).unwrap(), b\\"second!\\\\n\\");\\n        assert_eq!(fs::metadata(&input).unwrap().modified().unwrap(), different_old_time);\\n    }\\n\\n    #[test]\\n    fn archive_snapshot_reproduces_stale_ninja_test_object() {\\n        let root = tempfile::tempdir().unwrap();\\n        let local = root.path().join(\\"local\\");\\n        let checkout = root.path().join(\\"checkout\\");\\n        fs::create_dir(&local).unwrap();\\n        fs::create_dir(&checkout).unwrap();\\n        let input = local.join(\\"test.cc\\");\\n        let imported = checkout.join(\\"test.cc\\");\\n        let old_time = std::time::UNIX_EPOCH + std::time::Duration::from_secs(10_000);\\n        let archive_import = || run(Command::new(\\"rsync\\")\\n            .args([\\"-a\\", \\"--delete\\", \\"--exclude\\", \\".git\\"])\\n            .arg(format!(\\"{}/\\", local.display())).arg(&checkout)).unwrap();\\n        fs::write(&input, b\\"old tests\\\\n\\").unwrap();\\n        fs::File::open(&input).unwrap().set_modified(old_time).unwrap();\\n        archive_import();\\n        write(&root.path().join(\\"build.ninja\\"), format!(\\n            \\"rule compile\\\\n  command = cp $in $out\\\\nbuild result: compile {}\\\\n\\",\\n            imported.display())).unwrap();\\n        let ninja = || output(Command::new(\\"ninja\\").current_dir(root.path())).unwrap();\\n        ninja();\\n        fs::write(&input, b\\"new and additional tests\\\\n\\").unwrap();\\n        fs::File::open(&input).unwrap().set_modified(old_time).unwrap();\\n        archive_import();\\n        assert_eq!(fs::read(&imported).unwrap(), b\\"new and additional tests\\\\n\\");\\n        assert!(fs::metadata(&imported).unwrap().modified().unwrap()\\n            < fs::metadata(root.path().join(\\"result\\")).unwrap().modified().unwrap());\\n        assert!(ninja().contains(\\"no work to do\\"));\\n        // This is an intentional reproduction of the old bug, not a valid\\n        // build: authenticated new source bytes coexist with stale output.\\n        assert_eq!(fs::read(root.path().join(\\"result\\")).unwrap(), b\\"old tests\\\\n\\");\\n    }\\n\\n    #[test]\\n    #[ignore = \\"requires network access to fetch the published source pin\\"]\\n    fn published_source_pin_fetches_and_verifies() {\\n        let root = tempfile::tempdir().unwrap();\\n        fs::create_dir_all(root.path().join(\\"android/manifest\\")).unwrap();\\n        fs::write(\\n            root.path().join(\\"android/manifest/native-bridge-lock.json\\"),\\n            LOCK,\\n        )\\n        .unwrap();\\n        let source = root.path().join(\\"source\\");\\n        let result = prepare_source_with_local(root.path(), &source, None).unwrap();\\n        let lock: SourceLock = serde_json::from_str(LOCK).unwrap();\\n        assert_eq!(result[\\"commit\\"], lock.commit);\\n        assert_eq!(result[\\"working_tree\\"], false);\\n        assert_eq!(\\n            prepare_source_with_local(root.path(), &source, None).unwrap(),\\n            result\\n        );\\n    }\\n\\n    #[test]\\n    fn bridge_properties_replace_conflicts_and_preserve_system_identity() {\\n        let original = \\"ro.build.version.sdk=37\\\\nro.product.cpu.abi=x86_64\\\\nro.dalvik.vm.native.bridge=0\\\\nro.product.cpu.abilist=x86_64\\\\n\\";\\n        let changed = bridge_properties(original).unwrap();\\n        assert!(changed.contains(\\"ro.product.cpu.abi=x86_64\\\\n\\"));\\n        assert!(!changed.contains(\\"ro.dalvik.vm.native.bridge=0\\\\n\\"));\\n        for (key, value) in PROPERTIES {\\n            assert_eq!(\\n                changed\\n                    .lines()\\n                    .filter(|line| line.starts_with(&format!(\\"{key}=\\")))\\n                    .collect::<Vec<_>>(),\\n                vec![format!(\\"{key}={value}\\")]\\n            );\\n        }\\n        assert!(bridge_properties(\\"ro.build.version.sdk=36\\\\n\\").is_err());\\n    }\\n}\\n\\nfn validate_source_lock(lock: &SourceLock) -> Result<()> {\\n    if lock.schema_version != 1\\n        || lock.url != \\"https://github.com/denialwm/teto.git\\"\\n        || lock.path != \\"frameworks/libs/binary_translation\\"\\n        || lock.license != \\"Apache-2.0\\"\\n        || lock.commit.len() != 40\\n        || !lock\\n            .commit\\n            .bytes()\\n            .all(|b| b.is_ascii_digit() || (b\'a\'..=b\'f\').contains(&b))\\n    {\\n        return fail(\\"invalid Teto source lock\\");\\n    }\\n    Ok(())\\n}\\n\\npub fn prepare_source(repo: &Path, source: &Path) -> Result<serde_json::Value> {\\n    prepare_source_with_local(\\n        repo,\\n        source,\\n        std::env::var_os(\\"DROIDLOOM_NATIVE_BRIDGE_SOURCE\\").map(PathBuf::from),\\n    )\\n}\\n\\nfn prepare_source_with_local(\\n    repo: &Path,\\n    source: &Path,\\n    local: Option<PathBuf>,\\n) -> Result<serde_json::Value> {\\n    let lock: SourceLock = serde_json::from_slice(&fs::read(\\n        repo.join(\\"android/manifest/native-bridge-lock.json\\"),\\n    )?)?;\\n    validate_source_lock(&lock)?;\\n    let checkout = source.join(&lock.path);\\n    if let Some(local) = local {\\n        let local = local.canonicalize()?;\\n        if local.starts_with(source.canonicalize()?) {\\n            return fail(\\n                \\"Teto development checkout must be outside the generated AOSP source tree\\",\\n            );\\n        }\\n        if output(\\n            Command::new(\\"git\\")\\n                .arg(\\"-C\\")\\n                .arg(&local)\\n                .args([\\"remote\\", \\"get-url\\", \\"origin\\"]),\\n        )? != lock.url\\n        {\\n            return fail(\\"local Teto checkout must use the locked origin\\");\\n        }\\n        // A development branch can commit fixes on top of the published Teto pin.\\n        // Keep the base check while recording the actual revision being built.\\n        run(Command::new(\\"git\\").arg(\\"-C\\").arg(&local).args([\\n            \\"merge-base\\",\\n            \\"--is-ancestor\\",\\n            &lock.commit,\\n            \\"HEAD\\",\\n        ]))?;\\n        let head = output(\\n            Command::new(\\"git\\")\\n                .arg(\\"-C\\")\\n                .arg(&local)\\n                .args([\\"rev-parse\\", \\"HEAD\\"]),\\n        )?;\\n        let files = source_inventory(&local)?;\\n        fs::create_dir_all(&checkout)?;\\n        // Snapshot the actual working files. Compare content, not the source\'s\\n        // size/mtime, and do not import its timestamps: a different checkout can\\n        // contain new bytes older than existing Ninja objects. Changed bytes\\n        // must receive the import time; identical bytes retain the destination\\n        // time so repeated builds remain incremental. Never mutate the local\\n        // checkout or apply functional patches there.\\n        run(Command::new(\\"rsync\\")\\n            .args([\\"-a\\", \\"--checksum\\", \\"--no-times\\", \\"--delete\\", \\"--exclude\\", \\".git\\"])\\n            .arg(format!(\\"{}/\\", local.display()))\\n            .arg(&checkout))?;\\n        if source_inventory(&checkout)? != files || source_inventory(&local)? != files {\\n            return fail(\\"Digitalis working files changed while snapshotting; retry the build\\");\\n        }\\n        eprintln!(\\"Building Teto working files based on {}\\", lock.commit);\\n        return Ok(\\n            serde_json::json!({\\"commit\\": head, \\"base_commit\\": lock.commit,\\n                \\"working_tree\\": true, \\"files\\": files}),\\n        );\\n    }\\n    if !checkout.exists() {\\n        let parent = checkout.parent().ok_or(\\"source checkout has no parent\\")?;\\n        fs::create_dir_all(parent)?;\\n        let temporary = tempfile::Builder::new()\\n            .prefix(\\".teto-\\")\\n            .tempdir_in(parent)?;\\n        run(Command::new(\\"git\\")\\n            .arg(\\"init\\")\\n            .arg(\\"--quiet\\")\\n            .arg(temporary.path()))?;\\n        run(Command::new(\\"git\\")\\n            .arg(\\"-C\\")\\n            .arg(temporary.path())\\n            .args([\\"remote\\", \\"add\\", \\"origin\\", &lock.url]))?;\\n        run(Command::new(\\"git\\").arg(\\"-C\\").arg(temporary.path()).args([\\n            \\"fetch\\",\\n            \\"--depth\\",\\n            \\"1\\",\\n            \\"origin\\",\\n            &lock.commit,\\n        ]))?;\\n        run(Command::new(\\"git\\").arg(\\"-C\\").arg(temporary.path()).args([\\n            \\"checkout\\",\\n            \\"--detach\\",\\n            &lock.commit,\\n        ]))?;\\n        fs::rename(temporary.path(), &checkout)?;\\n    }\\n    for (args, expected) in [\\n        (vec![\\"rev-parse\\", \\"HEAD\\"], lock.commit.as_str()),\\n        (vec![\\"remote\\", \\"get-url\\", \\"origin\\"], lock.url.as_str()),\\n        (vec![\\"status\\", \\"--porcelain\\", \\"--untracked-files=all\\"], \\"\\"),\\n    ] {\\n        if output(Command::new(\\"git\\").arg(\\"-C\\").arg(&checkout).args(args))? != expected {\\n            return fail(\\"Teto checkout differs from its source lock or has local changes\\");\\n        }\\n    }\\n    eprintln!(\\"Verified {} at {}\\", lock.name, lock.commit);\\n    Ok(serde_json::json!({\\"commit\\": lock.commit, \\"working_tree\\": false}))\\n}\\n\\npub(crate) fn source_inventory(root: &Path) -> Result<BTreeMap<String, String>> {\\n    fn visit(root: &Path, dir: &Path, result: &mut BTreeMap<String, String>) -> Result<()> {\\n        for entry in fs::read_dir(dir)? {\\n            let entry = entry?;\\n            if entry.file_name() == \\".git\\" {\\n                continue;\\n            }\\n            let path = entry.path();\\n            let kind = entry.file_type()?;\\n            let relative = path.strip_prefix(root)?.to_string_lossy().into_owned();\\n            if kind.is_dir() {\\n                visit(root, &path, result)?;\\n            } else if kind.is_symlink() {\\n                if !path.canonicalize()?.starts_with(root) {\\n                    return fail(\\"Teto source symlink escapes its checkout\\");\\n                }\\n                result.insert(relative, format!(\\"link:{}\\", fs::read_link(path)?.display()));\\n            } else if kind.is_file() {\\n                result.insert(relative, hash(&path)?);\\n            } else {\\n                return fail(\\"unsupported object in Teto checkout\\");\\n            }\\n        }\\n        Ok(())\\n    }\\n    let mut result = BTreeMap::new();\\n    visit(root, root, &mut result)?;\\n    Ok(result)\\n}\\n", "delta/tools/droidloom-update/src/native_generation.rs": "//! Bind the private ART/engine generation ABI to the actual staged bytes.\\n//! This checks pairing. It does not certify an ART build, bypass APEX signature\\n//! verification, or turn a host/fixture result into Android qualification.\\nuse crate::util::*;\\nuse serde::{Deserialize, Serialize};\\nuse std::{collections::BTreeSet, fs, io::{Read, Write}, path::Path, process::{Command, Stdio}};\\n\\nconst PROTOCOL: &str = \\"DLOOMGE1-PROCMET2\\";\\nconst PRODUCT_RECORD: &str = \\"droidloom-native-generation-pair.json\\";\\npub(crate) const TREE_RECORD: &str = \\"system/etc/droidloom-native-generation-pair.json\\";\\nconst ENGINE: &str = \\"system/lib64/libberberis_arm64.so\\";\\nconst ART_APEX: &str = \\"system/apex/com.android.art.apex\\";\\n\\n#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]\\n#[serde(deny_unknown_fields)]\\npub(crate) struct Contract {\\n    schema: u32,\\n    abi: u32,\\n    protocol: String,\\n    host_abi: String,\\n    engine_sha256: String,\\n    art_apex_sha256: String,\\n    libart_sha256: String,\\n    libnativebridge_sha256: String,\\n    apex_pubkey_sha256: String,\\n}\\nimpl Contract {\\n    fn validate(&self) -> Result<()> {\\n        if self.schema != 1 || self.abi != 1 || self.protocol != PROTOCOL || self.host_abi != \\"x86_64\\" {\\n            return fail(\\"unsupported private native-generation pair contract\\");\\n        }\\n        for digest in [&self.engine_sha256, &self.art_apex_sha256, &self.libart_sha256,\\n                       &self.libnativebridge_sha256, &self.apex_pubkey_sha256] {\\n            if digest.len() != 64 || !digest.bytes().all(|b| b.is_ascii_digit() || (b\'a\'..=b\'f\').contains(&b)) {\\n                return fail(\\"invalid native-generation component SHA256\\");\\n            }\\n        }\\n        Ok(())\\n    }\\n}\\nfn regular(path: &Path) -> Result<()> {\\n    let meta = fs::symlink_metadata(path)?;\\n    if !meta.is_file() || meta.len() == 0 {\\n        return fail(format!(\\"expected nonempty regular native-generation component: {}\\", path.display()));\\n    }\\n    Ok(())\\n}\\nfn marker(bytes: &[u8], role: &str) -> Result<bool> {\\n    if bytes.len() < 20 || &bytes[..6] != b\\"\\\\x7fELF\\\\x02\\\\x01\\"\\n        || u16::from_le_bytes([bytes[16], bytes[17]]) != 3\\n        || u16::from_le_bytes([bytes[18], bytes[19]]) != 62 {\\n        return fail(\\"native-generation pairing requires x86_64 little-endian shared ELF components\\");\\n    }\\n    let prefix = b\\"DROIDLOOM_NATIVE_GENERATION=\\";\\n    let mut states = BTreeSet::new();\\n    for (position, window) in bytes.windows(prefix.len()).enumerate() {\\n        if window != prefix { continue; }\\n        let rest = &bytes[position..];\\n        let mut matched = false;\\n        for enabled in [false, true] {\\n            let expected = format!(\\"DROIDLOOM_NATIVE_GENERATION={};ROLE={role};ABI=1;PROTOCOL={PROTOCOL};\\",\\n                                   if enabled { 1 } else { 0 });\\n            if rest.starts_with(expected.as_bytes()) && rest.get(expected.len()) == Some(&0) {\\n                states.insert(enabled);\\n                matched = true;\\n            }\\n        }\\n        if !matched { return fail(\\"malformed, foreign-role, or unsupported compiled generation marker\\"); }\\n    }\\n    match states.len() {\\n        0 => Ok(false), // Legacy components are supported only with the feature disabled.\\n        1 => Ok(*states.first().unwrap()),\\n        _ => fail(\\"ambiguous compiled generation modes\\"),\\n    }\\n}\\nfn bytes_sha(bytes: &[u8]) -> String {\\n    use sha2::{Digest, Sha256};\\n    hex::encode(Sha256::digest(bytes))\\n}\\nstruct Apex {\\n    digest: String,\\n    pubkey: Vec<u8>,\\n    art: Vec<u8>,\\n    bridge: Vec<u8>,\\n}\\nfn extract_zip_member(apex: &Path, member: &str, destination: &Path) -> Result<()> {\\n    run(Command::new(\\"unzip\\").args([\\"-p\\"]).arg(apex).arg(member)\\n        .stdout(Stdio::from(fs::File::create(destination)?)))\\n}\\nfn inspect_apex(path: &Path) -> Result<Apex> {\\n    regular(path)?;\\n    let names = output(Command::new(\\"unzip\\").arg(\\"-Z1\\").arg(path))?;\\n    for required in [\\"apex_payload.img\\", \\"apex_pubkey\\"] {\\n        if names.lines().filter(|name| *name == required).count() != 1 {\\n            return fail(format!(\\"APEX must contain exactly one {required}\\"));\\n        }\\n    }\\n    let before = hash(path)?;\\n    let work = tempfile::Builder::new().prefix(\\"generation-apex-\\").tempdir()?;\\n    let payload = work.path().join(\\"payload.img\\");\\n    let key = work.path().join(\\"apex_pubkey\\");\\n    extract_zip_member(path, \\"apex_payload.img\\", &payload)?;\\n    extract_zip_member(path, \\"apex_pubkey\\", &key)?;\\n    regular(&key)?;\\n    let mut header = [0u8; 1082];\\n    fs::File::open(&payload)?.read_exact(&mut header)?;\\n    let art = work.path().join(\\"libart.so\\");\\n    let bridge = work.path().join(\\"libnativebridge.so\\");\\n    if header[1080..1082] == [0x53, 0xef] {\\n        // debugfs opens regular images read-only. All internal paths are constants.\\n        for (internal, destination) in [(\\"/lib64/libart.so\\", &art), (\\"/lib64/libnativebridge.so\\", &bridge)] {\\n            run(Command::new(\\"debugfs\\").arg(\\"-R\\").arg(format!(\\"cat {internal}\\")).arg(&payload)\\n                .stdout(Stdio::from(fs::File::create(destination)?)))?;\\n        }\\n    } else if header[1024..1028] == [0xe2, 0xe1, 0xf5, 0xe0] {\\n        let tree = work.path().join(\\"tree\\");\\n        fs::create_dir(&tree)?;\\n        run(Command::new(\\"fsck.erofs\\").arg(format!(\\"--extract={}\\", tree.display())).arg(&payload))?;\\n        regular(&tree.join(\\"lib64/libart.so\\"))?;\\n        regular(&tree.join(\\"lib64/libnativebridge.so\\"))?;\\n        fs::copy(tree.join(\\"lib64/libart.so\\"), &art)?;\\n        fs::copy(tree.join(\\"lib64/libnativebridge.so\\"), &bridge)?;\\n    } else {\\n        return fail(\\"unsupported ART APEX payload filesystem\\");\\n    }\\n    regular(&art)?;\\n    regular(&bridge)?;\\n    if hash(path)? != before { return fail(\\"ART APEX changed while being inspected\\"); }\\n    Ok(Apex { digest: before, pubkey: fs::read(key)?, art: fs::read(art)?, bridge: fs::read(bridge)? })\\n}\\nfn read_contract(path: &Path) -> Result<Contract> {\\n    regular(path)?;\\n    let contract: Contract = serde_json::from_slice(&fs::read(path)?)?;\\n    contract.validate()?;\\n    Ok(contract)\\n}\\nfn verify_components(engine: &[u8], apex: &Apex, contract: Option<&Contract>) -> Result<bool> {\\n    let modes = [marker(engine, \\"ENGINE\\")?, marker(&apex.art, \\"ART_RUNTIME\\")?,\\n                 marker(&apex.bridge, \\"ART_BRIDGE\\")?];\\n    if modes.iter().all(|enabled| !enabled) {\\n        if contract.is_some() { return fail(\\"generation contract supplied for disabled or legacy components\\"); }\\n        return Ok(false);\\n    }\\n    if !modes.iter().all(|enabled| *enabled) {\\n        return fail(\\"mixed ART/runtime/engine generation modes; rebuild the complete paired artifacts\\");\\n    }\\n    let contract = contract.ok_or(\\"enabled generation requires an exact component pair contract\\")?;\\n    contract.validate()?;\\n    if bytes_sha(engine) != contract.engine_sha256 || apex.digest != contract.art_apex_sha256\\n        || bytes_sha(&apex.art) != contract.libart_sha256\\n        || bytes_sha(&apex.bridge) != contract.libnativebridge_sha256\\n        || bytes_sha(&apex.pubkey) != contract.apex_pubkey_sha256 {\\n        return fail(\\"native-generation contract does not match actual staged component bytes\\");\\n    }\\n    Ok(true)\\n}\\n/// Create the pair record from already built enabled components. This does not\\n/// enable a build option, certify a build, verify an APEX signature, or install\\n/// anything. Staging and bundle verification independently re-read the bytes.\\npub(crate) fn create_product_contract(product: &Path) -> Result<Contract> {\\n    if !product.is_absolute()\\n        || product.components().any(|part| matches!(part,\\n            std::path::Component::ParentDir | std::path::Component::CurDir)) {\\n        return fail(\\"native-generation product must be an absolute directory without aliases\\");\\n    }\\n    for path in product.ancestors() {\\n        if !fs::symlink_metadata(path)?.is_dir() {\\n            return fail(\\"native-generation product and its parents must be real directories\\");\\n        }\\n    }\\n    let engine_path = product.join(ENGINE);\\n    let apex_path = product.join(ART_APEX);\\n    regular(&engine_path)?;\\n    let engine = fs::read(&engine_path)?;\\n    let apex = inspect_apex(&apex_path)?;\\n    let contract = Contract {\\n        schema: 1, abi: 1, protocol: PROTOCOL.into(), host_abi: \\"x86_64\\".into(),\\n        engine_sha256: bytes_sha(&engine), art_apex_sha256: apex.digest.clone(),\\n        libart_sha256: bytes_sha(&apex.art), libnativebridge_sha256: bytes_sha(&apex.bridge),\\n        apex_pubkey_sha256: bytes_sha(&apex.pubkey),\\n    };\\n    // A supplied contract is rejected for disabled/legacy or mixed components.\\n    // An old PROCMET1 role is rejected even when all its hashes are consistent.\\n    verify_components(&engine, &apex, Some(&contract))?;\\n    if hash(&engine_path)? != contract.engine_sha256 || hash(&apex_path)? != apex.digest {\\n        return fail(\\"native-generation product changed while forming its pair record\\");\\n    }\\n    let mut temporary = tempfile::NamedTempFile::new_in(product)?;\\n    temporary.write_all(&serde_json::to_vec_pretty(&contract)?)?;\\n    temporary.write_all(b\\"\\\\n\\")?;\\n    temporary.as_file().sync_all()?;\\n    // Atomic and create-only: an existing record, including a symlink, is never\\n    // replaced. The temporary file is retired if publication is rejected.\\n    temporary.persist_noclobber(product.join(PRODUCT_RECORD))?;\\n    fs::File::open(product)?.sync_all()?;\\n    Ok(contract)\\n}\\npub(crate) fn verify_tree(tree: &Path) -> Result<bool> {\\n    let engine = tree.join(ENGINE);\\n    regular(&engine)?;\\n    let contract = if tree.join(TREE_RECORD).exists() {\\n        Some(read_contract(&tree.join(TREE_RECORD))?)\\n    } else { None };\\n    let apex = inspect_apex(&tree.join(ART_APEX))?;\\n    verify_components(&fs::read(engine)?, &apex, contract.as_ref())\\n}\\n/// Called in the existing fakeroot image transaction after copying the engine.\\n/// Preserve the base APEX inode metadata; replace the entire signed APEX file.\\npub(crate) fn stage_product(product: &Path, tree: &Path) -> Result<Option<Contract>> {\\n    if !product.join(PRODUCT_RECORD).exists() {\\n        verify_tree(tree)?; // An enabled engine cannot silently use the old ART APEX.\\n        return Ok(None);\\n    }\\n    let contract = read_contract(&product.join(PRODUCT_RECORD))?;\\n    let proposed = inspect_apex(&product.join(ART_APEX))?;\\n    let base = inspect_apex(&tree.join(ART_APEX))?;\\n    if proposed.pubkey != base.pubkey {\\n        return fail(\\"candidate ART APEX uses a different payload verification key\\");\\n    }\\n    regular(&tree.join(ENGINE))?;\\n    verify_components(&fs::read(tree.join(ENGINE))?, &proposed, Some(&contract))?;\\n    let mut input = fs::File::open(product.join(ART_APEX))?;\\n    let mut output = fs::OpenOptions::new().write(true).truncate(true).open(tree.join(ART_APEX))?;\\n    std::io::copy(&mut input, &mut output)?;\\n    output.flush()?;\\n    let record = tree.join(TREE_RECORD);\\n    fs::write(&record, serde_json::to_vec_pretty(&contract)?)?;\\n    mode(&record, 0o644)?;\\n    run(Command::new(\\"chown\\").arg(\\"0:0\\").arg(&record))?;\\n    run(Command::new(\\"setfattr\\").args([\\"-n\\", \\"security.selinux\\", \\"-v\\", \\"u:object_r:system_file:s0\\"]).arg(&record))?;\\n    verify_tree(tree)?;\\n    Ok(Some(contract))\\n}\\n/// The existing installer invokes bundle::verify on its private root-owned copy.\\n/// Re-extract those actual image bytes so a stale JSON record cannot authorize\\n/// an old ART or a different engine. This does not activate the image.\\npub(crate) fn verify_bundle(root: &Path) -> Result<()> {\\n    let image = root.join(\\"var/lib/droidloom/images/images/system.img\\");\\n    if !image.exists() {\\n        // Unit fixtures and historical non-image bundles have no enabled pair.\\n        return Ok(());\\n    }\\n    regular(&image)?;\\n    let before = hash(&image)?;\\n    let work = tempfile::Builder::new().prefix(\\"generation-image-verify-\\").tempdir()?;\\n    let tree = work.path().join(\\"tree\\");\\n    fs::create_dir(&tree)?;\\n    // Content verification only: no privileged ownership/xattrs need applying.\\n    run(Command::new(\\"fsck.erofs\\").arg(format!(\\"--extract={}\\", tree.display())).arg(&image))?;\\n    verify_tree(&tree)?;\\n    if hash(&image)? != before { return fail(\\"system image changed during generation verification\\"); }\\n    Ok(())\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n    fn elf(role: &str, mode: Option<u8>) -> Vec<u8> {\\n        let mut bytes = vec![0; 64];\\n        bytes[..6].copy_from_slice(b\\"\\\\x7fELF\\\\x02\\\\x01\\");\\n        bytes[16] = 3; bytes[18] = 62;\\n        if let Some(mode) = mode {\\n            bytes.extend(format!(\\"DROIDLOOM_NATIVE_GENERATION={mode};ROLE={role};ABI=1;PROTOCOL={PROTOCOL};\\\\0\\").bytes());\\n        }\\n        bytes\\n    }\\n    fn fixture(modes: [Option<u8>; 3]) -> (Vec<u8>, Apex, Contract) {\\n        let engine = elf(\\"ENGINE\\", modes[0]);\\n        let apex = Apex { digest: \\"a\\".repeat(64), pubkey: b\\"owned fixture key\\".to_vec(),\\n                         art: elf(\\"ART_RUNTIME\\", modes[1]), bridge: elf(\\"ART_BRIDGE\\", modes[2]) };\\n        let contract = Contract { schema: 1, abi: 1, protocol: PROTOCOL.into(), host_abi: \\"x86_64\\".into(),\\n            engine_sha256: bytes_sha(&engine), art_apex_sha256: apex.digest.clone(),\\n            libart_sha256: bytes_sha(&apex.art), libnativebridge_sha256: bytes_sha(&apex.bridge),\\n            apex_pubkey_sha256: bytes_sha(&apex.pubkey) };\\n        (engine, apex, contract)\\n    }\\n    #[test]\\n    fn legacy_and_disabled_preserve_the_disabled_mode() {\\n        for modes in [[None,None,None],[Some(0),Some(0),Some(0)],[None,Some(0),None]] {\\n            let (engine, apex, _) = fixture(modes);\\n            assert!(!verify_components(&engine, &apex, None).unwrap());\\n        }\\n    }\\n    #[test]\\n    fn rejects_every_mixed_old_new_combination() {\\n        for bits in 1..7 {\\n            let modes = std::array::from_fn(|i| if bits & (1 << i) != 0 { Some(1) } else { None });\\n            let (engine, apex, contract) = fixture(modes);\\n            assert!(verify_components(&engine, &apex, Some(&contract)).is_err(), \\"{bits}\\");\\n        }\\n    }\\n    #[test]\\n    fn enabled_triplet_requires_exact_contract() {\\n        let (engine, apex, contract) = fixture([Some(1);3]);\\n        assert!(verify_components(&engine, &apex, Some(&contract)).unwrap());\\n        assert!(verify_components(&engine, &apex, None).is_err());\\n        for key in [\\"engine_sha256\\",\\"art_apex_sha256\\",\\"libart_sha256\\",\\"libnativebridge_sha256\\",\\"apex_pubkey_sha256\\"] {\\n            let mut json = serde_json::to_value(&contract).unwrap();\\n            json[key] = \\"0\\".repeat(64).into();\\n            let wrong: Contract = serde_json::from_value(json).unwrap();\\n            assert!(verify_components(&engine, &apex, Some(&wrong)).is_err(), \\"{key}\\");\\n        }\\n    }\\n    #[test]\\n    fn rejects_malformed_foreign_or_ambiguous_marker() {\\n        for bytes in [elf(\\"ART_BRIDGE\\",Some(1)),elf(\\"ENGINE\\",Some(2))] {\\n            assert!(marker(&bytes,\\"ENGINE\\").is_err());\\n        }\\n        let mut ambiguous = elf(\\"ENGINE\\",Some(0));\\n        ambiguous.extend_from_slice(&elf(\\"ENGINE\\",Some(1))[64..]);\\n        assert!(marker(&ambiguous,\\"ENGINE\\").is_err());\\n        let mut unknown = elf(\\"ENGINE\\",Some(1));\\n        *unknown.last_mut().unwrap() = b\'x\';\\n        assert!(marker(&unknown,\\"ENGINE\\").is_err());\\n    }\\n    #[test]\\n    fn rejects_foreign_elf_and_unrecognized_contract() {\\n        let (mut engine, apex, contract) = fixture([Some(1);3]);\\n        engine[18] = 183;\\n        assert!(verify_components(&engine,&apex,Some(&contract)).is_err());\\n        for (key,value) in [(\\"abi\\",serde_json::json!(2)),(\\"protocol\\",serde_json::json!(\\"old\\")),\\n                            (\\"host_abi\\",serde_json::json!(\\"aarch64\\")),(\\"engine_sha256\\",serde_json::json!(\\"../bad\\"))] {\\n            let mut json = serde_json::to_value(&contract).unwrap();json[key]=value;\\n            assert!(serde_json::from_value::<Contract>(json).unwrap().validate().is_err());\\n        }\\n        let mut json = serde_json::to_value(&contract).unwrap();json[\\"ignored\\"]=true.into();\\n        assert!(serde_json::from_value::<Contract>(json).is_err());\\n    }\\n    #[test]\\n    fn rejects_symlinked_components() {\\n        let work=tempfile::tempdir().unwrap();\\n        fs::write(work.path().join(\\"real\\"),b\\"content\\").unwrap();\\n        std::os::unix::fs::symlink(\\"real\\",work.path().join(\\"link\\")).unwrap();\\n        assert!(regular(&work.path().join(\\"link\\")).is_err());\\n    }\\n    fn previous_protocol_elf(role: &str, mode: u8) -> Vec<u8> {\\n        let mut bytes = elf(role, None);\\n        bytes.extend(format!(\\"DROIDLOOM_NATIVE_GENERATION={mode};ROLE={role};ABI=1;PROTOCOL=DLOOMGE1-PROCMET1;\\\\0\\").bytes());\\n        bytes\\n    }\\n    #[test]\\n    fn rejects_previous_protocol_for_each_role_and_mode() {\\n        for role in [\\"ENGINE\\", \\"ART_RUNTIME\\", \\"ART_BRIDGE\\"] {\\n            for mode in [0, 1] {\\n                assert!(marker(&previous_protocol_elf(role, mode), role).is_err(), \\"{role}/{mode}\\");\\n            }\\n        }\\n    }\\n    #[test]\\n    fn rejects_previous_protocol_inside_self_consistent_enabled_contract() {\\n        for role in [\\"ENGINE\\", \\"ART_RUNTIME\\", \\"ART_BRIDGE\\"] {\\n            let (mut engine, mut apex, mut contract) = fixture([Some(1); 3]);\\n            match role {\\n                \\"ENGINE\\" => engine = previous_protocol_elf(role, 1),\\n                \\"ART_RUNTIME\\" => apex.art = previous_protocol_elf(role, 1),\\n                \\"ART_BRIDGE\\" => apex.bridge = previous_protocol_elf(role, 1),\\n                _ => unreachable!(),\\n            }\\n            contract.engine_sha256 = bytes_sha(&engine);\\n            contract.libart_sha256 = bytes_sha(&apex.art);\\n            contract.libnativebridge_sha256 = bytes_sha(&apex.bridge);\\n            assert!(verify_components(&engine, &apex, Some(&contract)).is_err(), \\"{role}\\");\\n        }\\n    }\\n    #[test]\\n    fn rejects_previous_protocol_contract() {\\n        let (engine, apex, mut contract) = fixture([Some(1); 3]);\\n        contract.protocol = \\"DLOOMGE1-PROCMET1\\".into();\\n        assert!(verify_components(&engine, &apex, Some(&contract)).is_err());\\n    }\\n    fn image_fixture(work: &Path, modes: [Option<u8>;3]) -> (std::path::PathBuf, Contract) {\\n        let (engine, apex, mut contract) = fixture(modes);\\n        let payload_tree=work.join(\\"payload-tree\\");fs::create_dir_all(payload_tree.join(\\"lib64\\")).unwrap();\\n        fs::write(payload_tree.join(\\"lib64/libart.so\\"),&apex.art).unwrap();\\n        fs::write(payload_tree.join(\\"lib64/libnativebridge.so\\"),&apex.bridge).unwrap();\\n        let payload=work.join(\\"apex_payload.img\\");\\n        fs::File::create(&payload).unwrap().set_len(16*1024*1024).unwrap();\\n        run(Command::new(\\"mke2fs\\").args([\\"-q\\",\\"-F\\",\\"-t\\",\\"ext4\\",\\"-d\\"]).arg(&payload_tree).arg(&payload)).unwrap();\\n        fs::write(work.join(\\"apex_pubkey\\"),&apex.pubkey).unwrap();\\n        let archive=work.join(\\"com.android.art.apex\\");\\n        run(Command::new(\\"zip\\").current_dir(work).arg(\\"-q\\").arg(&archive).args([\\"apex_payload.img\\",\\"apex_pubkey\\"])).unwrap();\\n        contract.art_apex_sha256=hash(&archive).unwrap();\\n        let tree=work.join(\\"system-tree\\");\\n        fs::create_dir_all(tree.join(\\"system/lib64\\")).unwrap();\\n        fs::create_dir_all(tree.join(\\"system/apex\\")).unwrap();\\n        fs::create_dir_all(tree.join(\\"system/etc\\")).unwrap();\\n        fs::write(tree.join(ENGINE),engine).unwrap();\\n        fs::copy(archive,tree.join(ART_APEX)).unwrap();\\n        (tree,contract)\\n    }\\n    #[test]\\n    fn real_ext4_apex_extraction_rejects_changed_nested_component() {\\n        let work=tempfile::tempdir().unwrap();\\n        let (tree,contract)=image_fixture(work.path(),[Some(1);3]);\\n        fs::write(tree.join(TREE_RECORD),serde_json::to_vec(&contract).unwrap()).unwrap();\\n        assert!(verify_tree(&tree).unwrap());\\n        let mut changed=contract.clone();changed.libart_sha256=\\"0\\".repeat(64);\\n        fs::write(tree.join(TREE_RECORD),serde_json::to_vec(&changed).unwrap()).unwrap();\\n        assert!(verify_tree(&tree).is_err());\\n        fs::remove_file(tree.join(TREE_RECORD)).unwrap();\\n        assert!(verify_tree(&tree).is_err());\\n    }\\n    #[test]\\n    fn product_contract_generation_requires_enabled_triplet() {\\n        for modes in [[None; 3], [Some(0); 3]] {\\n            let work = tempfile::tempdir().unwrap();\\n            let (product, _) = image_fixture(work.path(), modes);\\n            assert!(create_product_contract(&product).is_err());\\n            assert!(!product.join(PRODUCT_RECORD).exists());\\n        }\\n    }\\n    #[test]\\n    fn product_contract_generation_is_create_only_and_binds_components() {\\n        let work = tempfile::tempdir().unwrap();\\n        let (product, expected) = image_fixture(work.path(), [Some(1); 3]);\\n        let observed = create_product_contract(&product).unwrap();\\n        assert_eq!(observed, expected);\\n        let record = product.join(PRODUCT_RECORD);\\n        assert_eq!(read_contract(&record).unwrap(), expected);\\n        let before = fs::read(&record).unwrap();\\n        assert!(create_product_contract(&product).is_err());\\n        assert_eq!(fs::read(&record).unwrap(), before);\\n        fs::write(product.join(ENGINE), previous_protocol_elf(\\"ENGINE\\", 1)).unwrap();\\n        assert!(create_product_contract(&product).is_err());\\n        assert_eq!(fs::read(&record).unwrap(), before);\\n    }\\n    #[test]\\n    fn real_erofs_bundle_verifies_its_embedded_pair() {\\n        let work=tempfile::tempdir().unwrap();\\n        let (tree,contract)=image_fixture(work.path(),[Some(1);3]);\\n     